  background-repeat: no-repeat, repeat-x !important;
  background-size: 600px 600px, 100% 60px !important;
  background-position: center center, 0 0 !important;
  animation: cyberRadarSweep 6s linear infinite !important;
}
.chat-markdown-codeblock {
  backdrop-filter: blur(14px) !important;
  background: rgba(7, 18, 32, 0.76) !important;
  border: 1px solid rgba(0, 240, 255, 0.26) !important;
  box-shadow: 0 8px 24px rgba(0, 240, 255, 0.1) !important;
}
[data-chat-header] {
  backdrop-filter: blur(12px) !important;
  background: rgba(5, 11, 20, 0.82) !important;
  border-bottom: 1px solid rgba(0, 240, 255, 0.18) !important;
}
